import unittest
from orders import latest_orders

class LatestOrdersTests(unittest.TestCase):
    def test_zero_count(self):
        self.assertEqual(latest_orders([9, 1, 4], 0), [])
    def test_positive_count(self):
        orders = [9, 1, 4]
        self.assertEqual(latest_orders(orders, 2), [4, 9])
        self.assertEqual(orders, [9, 1, 4])

